-- 005: run ONCE after 004. Copies the 8 starter courses (full text) into the database; safe to re-run.

insert into public.courses (id, slug, title, category, price, mrp, duration, description, long_description, instructor, tag, icon, seo_title, seo_desc, learn, faq, rating, rating_count, real_rating, published, sort_order)
values (1, $q$ccc-computer-course$q$, $q$CCC Computer Course (NIELIT Pattern)$q$, $q$computer$q$, 999, 1999, $q$3 Months$q$, $q$Complete NIELIT syllabus: LibreOffice Writer, Calc, Impress, Internet and Cyber Security, with mock tests and bilingual notes.$q$, $q$The CCC (Course on Computer Concepts) is a basic IT literacy certificate that many government job forms and promotions ask for. This course follows the NIELIT exam pattern: you learn computer fundamentals, Windows, the internet, email, digital payments and the LibreOffice suite in simple Hindi and English, then practise with chapter quizzes and full-length mock tests so exam day feels familiar.$q$, $q$GCI India Faculty$q$, $q$Bestseller$q$, $q$desktop_windows$q$, $q$CCC Course Online in Hindi – NIELIT Pattern | GCI India$q$, $q$Prepare for the NIELIT CCC exam online with Hindi-English video lessons, practice on Writer, Calc and Impress, and mock tests. Enroll today.$q$, $q$["Computer fundamentals and Windows basics", "Hands-on practice in Writer, Calc and Impress", "Internet, email and cyber safety basics", "Digital payments, UPI and e-governance services", "Chapter quizzes and mock tests in the CCC exam pattern"]$q$::jsonb, $q$[["Is this course useful for government exams?", "CCC is asked in many state and central government recruitments and promotions. Check your own notification, then use this course to prepare for the NIELIT CCC exam."], ["Do I get the official NIELIT certificate?", "The NIELIT CCC certificate is issued by NIELIT after you pass their exam. This course prepares you for that exam and gives you a GCI India completion certificate."]]$q$::jsonb, 4.9, 4820, false, true, 10)
