insert into public.courses (id, slug, title, category, price, mrp, duration, description, long_description, instructor, tag, icon, seo_title, seo_desc, learn, faq, rating, rating_count, real_rating, published, sort_order)
values (2, $q$free-computer-basics-typing-course$q$, $q$Free Computer Fundamentals & Typing Mastery$q$, $q$computer$q$, 0, 0, $q$2 Weeks$q$, $q$Windows basics, shortcuts, folder management and Hindi/English touch typing to boost your clerical speed.$q$, $q$This free course is built for people who have never used a computer seriously. You start with the parts of a computer and Windows, learn to manage files and folders, use keyboard shortcuts, and then build typing speed in English and Hindi with daily practice drills. It is a good first step before CCC, O Level or any office job training.$q$, $q$GCI India Faculty$q$, $q$Free$q$, $q$keyboard$q$, $q$Free Computer Basics & Typing Course in Hindi | GCI India$q$, $q$Free online course for beginners: computer basics, Windows, keyboard shortcuts and Hindi and English typing practice. Learn at your own pace.$q$, $q$["Parts of a computer and how Windows works", "Creating, copying and organising files and folders", "Time-saving keyboard shortcuts", "English and Hindi typing practice drills", "Safe use of the internet for beginners"]$q$::jsonb, $q$[["Is this course really free?", "Yes. You can enroll for free and access all lessons without paying. You only need to create a free student account."], ["Do I need any computer knowledge?", "No. The course starts from the very basics and is taught in simple Hindi and English."]]$q$::jsonb, 4.8, 8910, false, true, 20)
