insert into public.courses (id, slug, title, category, price, mrp, duration, description, long_description, instructor, tag, icon, seo_title, seo_desc, learn, faq, rating, rating_count, real_rating, published, sort_order)
values (3, $q$ms-excel-mis-reporting-course$q$, $q$MS Excel & Advanced MIS Reporting$q$, $q$computer$q$, 699, 1499, $q$1 Month$q$, $q$XLOOKUP, Pivot Tables, dynamic dashboards and macro basics for corporate roles.$q$, $q$Excel is one of the most asked-for skills in office, accounts and MIS jobs. This course takes you from cell formatting and basic formulas to lookups, pivot tables, charts and dynamic dashboards, using practice files that look like real business data. You also learn how to automate repeated work and prepare clean MIS reports that managers can read at a glance.$q$, $q$GCI India Faculty$q$, $q$Bestseller$q$, $q$table_chart$q$, $q$MS Excel Course Online in Hindi – Formulas & MIS | GCI India$q$, $q$Learn MS Excel from basics to advanced: formulas, XLOOKUP, pivot tables and MIS dashboards. Practice files, Hindi-English lessons and a certificate.$q$, $q$["Formatting, sorting, filtering and data cleaning", "Core formulas, IF logic and XLOOKUP / VLOOKUP", "Pivot tables, charts and interactive dashboards", "Building MIS reports from raw data", "Basics of automating repeated tasks with macros"]$q$::jsonb, $q$[["Which Excel version is used?", "Lessons use modern Excel, and most techniques also work in older versions and in Google Sheets."], ["Will this help in an MIS or accounts job?", "The course focuses on the formulas, pivot tables and reports used daily in MIS and accounts roles, so it is a practical skill to show in interviews."]]$q$::jsonb, 4.9, 3150, false, true, 30)
