insert into public.courses (id, slug, title, category, price, mrp, duration, description, long_description, instructor, tag, icon, seo_title, seo_desc, learn, faq, rating, rating_count, real_rating, published, sort_order)
values (4, $q$amazon-flipkart-meesho-seller-course$q$, $q$Complete E-commerce Seller (Amazon, Flipkart, Meesho)$q$, $q$ecommerce$q$, 1499, 2999, $q$2 Months$q$, $q$Account setup, listings, GST, marketplace SEO, fulfilment, returns and sponsored ads, step by step.$q$, $q$Selling online in India means learning three different seller panels, GST rules, shipping models and advertising. This course walks you through each marketplace step by step: registering your seller account, preparing a product catalogue, writing listings that rank, choosing a fulfilment model, handling returns and running sponsored ads. It suits first-time sellers, small business owners and freelancers who want to manage seller accounts for clients.$q$, $q$Rajesh Kumar Verma$q$, $q$Highest rated$q$, $q$storefront$q$, $q$Amazon, Flipkart & Meesho Seller Course in Hindi | GCI India$q$, $q$Learn to sell online on Amazon, Flipkart and Meesho: account setup, GST basics, listings, ads and returns. Step-by-step Hindi course for new sellers.$q$, $q$["Registering seller accounts and the business documents needed", "Creating product listings with search-friendly titles", "Pricing, commission and profit calculation", "Shipping, fulfilment and return handling", "Running sponsored product ads"]$q$::jsonb, $q$[["Do I need GST to start selling?", "It depends on what you sell and where. The course explains when GST is required and how to register, so you can decide for your own business."], ["Can I manage seller accounts for clients after this course?", "Yes. The course covers account access and day-to-day operations, which are the skills needed to manage accounts as a freelancer."]]$q$::jsonb, 4.8, 2150, false, true, 40)
